  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://get.firstaidbeauty.com/MTI1Mw==', 'official_site', 'ugc_collab', 'First Aid Beauty''s own Creator Crew page (''Join the FAB Creator Crew: Real skin. Real voices.'') invites creators to apply through the Humanz app, states ''500 Creators partnered with FAB'', and promises ''Competitive compensation & perks'' and ''competitive pay'' — paid creator partnerships, with no commission percentage published on the page.', 'verified', now());
