  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lgbeauty.com/affiliate', 'official_site', 'affiliate', 'belif is recruited through parent LG Beauty''s Ambassador program — belif is shown among the brands on the official page, which takes applications and pays via Refersion (PayPal) and Impact (ACH). The same page conflicts with itself: benefits state ''Earn 10% commission on purchases made through your link and code'' while the FAQ states ''Commission rates start at 5% and can increase depending on your audience size, platform, and engagement.'' Because the brand''s own page does not settle one rate, the rate is recorded as null. Ambassadors must reside in the United States. No cap wording was found, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 7, 9, 7, 4, '{"niche_fit": "Aqua Bomb hydration products are long-standing skincare-UGC staples.", "ugc_evidence": "A formal parent-run ambassador program with application, links and codes; no hard creator count was published on fetched pages.", "compensation": "The official page quotes both 10% and a 5% starting rate in different sections, so no single rate is recorded; a paid commission clearly exists.", "contact_access": "Open application on the brand-owned LG Beauty affiliate page; no partnerships email is published.", "opportunity_availability": "Applications are open to US residents, with rates reviewed per applicant.", "credibility": "LG Household & Health Care brand founded in 2010 with Sephora distribution."}'::jsonb);
