  insert into public.brands (name, website, description, country, status) values ('Titan Fitness', 'https://titan.fitness', 'Memphis, Tennessee-based home-gym and fitness equipment company offering power racks, weight benches, barbells, weights and specialty machines for strength training and home or facility gym building. Its parent Titan Brands reports 50,000+ five-star customer reviews on its equipment.', 'United States', 'published') returning id into bid;
