  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://titan.fitness/pages/affiliate-program', 'official_site', 'affiliate', 'The brand''s official affiliate page allows approved websites and content creators to link to Titan Fitness and earn commissions: 5% commission, 30-day cookie, paid by the 15th of every month, run on the Impact platform, free to sign up, with a dedicated program manager, product-for-review opportunities and exclusive follower coupons; contact email affiliates@titan.fitness. No cap statement is published, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.prnewswire.com/news-releases/titan-fitness-launches-commercial-division-for-gyms-schools-and-training-facilities-302893252.html', 'article', 'company_background', 'PR Newswire describes Titan Brands as the Memphis-based company behind Titan Fitness; equipment includes racks, benches and free weights, with 50,000+ five-star reviews.', 'verified', now());
