  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 12, 15, 10, 5, '{"compensation": "5% flat is modest, partly offset by high equipment order values; no tier found on fetched pages and no cap statement, so the cap is unknown.", "contact_access": "Named affiliate email (affiliates@titan.fitness) and a dedicated program manager on the official page.", "credibility": "Official program page on a major network from an established US brand, corroborated by a third-party review.", "niche_fit": "Power racks, barbells, plates and budget home-gym builds are a direct fit for garage-gym and strength-training creators.", "opportunity_availability": "Live, free to join now via Impact from the official page; 30-day cookie, paid by the 15th monthly.", "ugc_evidence": "Official page explicitly offers product-for-review opportunities and exclusive follower coupons, plus banners and promotions."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Myprotein', 'https://www.myprotein.com', 'British sports-nutrition brand founded in 2004 and based in Manchester; part of the THG family since 2011. It sells protein powder, vitamins and minerals, high-protein foods, snack alternatives and performance clothing, and says it claimed the title of the world''s leading online sports nutrition brand in 2016.', 'United Kingdom', 'published') returning id into bid;
