  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.myprotein.com/c/about-us/ways-to-work-with-us/affiliated-partners/', 'official_site', 'affiliate', 'Myprotein''s official Affiliated Partners page invites ambassadors and affiliates to ''earn commission on sales you generate for us with a percentage as high as 8%'', with a 30-day cookie window and an in-house affiliate team. No cap statement is published, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.myprotein.com/c/about-us/ways-to-work-with-us/affiliated-partners/faq/', 'official_site', 'affiliate', 'The brand''s UK influencer FAQ (search-indexed; direct open was rate-limited in this run, flagged for re-verification) states up to 10% commission on tracked link sales, a 30-day cookie, product allowance and an exclusive discount code, and tells influencers with over 5,000 followers to email AmbassadorSchemeUK@myprotein.com.', 'publicly_reported', now());
