  insert into public.brands (name, website, description, country, status) values ('Saily', 'https://saily.com', 'Travel eSIM app created by Nord Security, which is headquartered in Vilnius, Lithuania. Saily offers eSIM plans in over 200 destinations, says it is trusted by over 14 million users, and describes itself as a new eSIM app that is growing fast; affiliates earn on each new user they refer, tracked with a 30-day cookie.', 'Lithuania', 'published') returning id into bid;
