  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Direct (in-house)', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://saily.com/affiliate/.', 'https://saily.com/affiliate/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Saily eSIM Affiliate Program', 'https://saily.com/affiliate/', 'https://saily.com/affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://saily.com/affiliate/', 'official_site', 'affiliate', 'Saily''s official affiliate page states ''earn 15% with every new user'' (per new user; not stated to recur on repeat purchases), with a 30-day cookie: ''If a sale happens within 30 days of a customer visiting Saily, you will still get paid for that sale.'' Joining is Register, then meet a dedicated partnership manager, then start earning. No cap statement is published, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://saily.com/affiliate/', 'official_site', 'ugc_collab', 'The page''s FAQ states a website or blog is not necessary: ''You can generate traffic through a YouTube channel or your social media accounts.'' Marketing assets and SEO support are provided.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://investlithuania.com/success-stories/nord-security/', 'article', 'company_background', 'Invest Lithuania reports Nord Security''s headquarters remain in Vilnius, Lithuania, and lists Saily among its products as ''a global eSIM service.''', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 18, 9, 9, 5, '{"compensation": "15% per new user is the highest clean, officially published rate in this batch; caveat: per new user only and eSIM order values are small.", "contact_access": "A dedicated partnership manager is promised after joining, but no email is published on the fetched page.", "credibility": "Official affiliate page fetched; Nord Security backing.", "niche_fit": "eSIM is a core, repeatable travel purchase; a single-product brand keeps the pitch simple.", "opportunity_availability": "Open registration with review on the official page.", "ugc_evidence": "Explicit social/YouTube eligibility in its FAQ, plus content tips, marketing assets and an affiliate guide; no creator counts published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PRx Performance', 'https://prxperformance.com', 'Fargo, North Dakota-based home-gym equipment company founded in 2013, known for space-saving folding and freestanding squat racks, barbells, plates, rigs and home-gym storage. It is a Shark Tank success story, described in a platform case study as one of USA Today''s 15 best-selling Shark Tank products of all time.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://uppromote.com/case-study/prx-performance/.', 'https://prxperformance.com/pages/register-affiliate-account', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PRx Performance Affiliate Program (via UpPromote)', 'https://prxperformance.com/pages/register-affiliate-account', 'https://prxperformance.com/pages/register-affiliate-account', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://prxperformance.com/pages/register-affiliate-account', 'official_site', 'affiliate', 'The brand''s own Affiliate Register Page exists on prxperformance.com, confirming a joinable affiliate program; the page rendered minimal text in this fetch, so no rate or email was extracted from it.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/case-study/prx-performance/', 'affiliate_network', 'affiliate', 'UpPromote''s case study: PRx runs its program on UpPromote with a performance-based commission structure from 5% up to 12% (5% is the starting rate; 12% is a rate ceiling, not an earnings cap), exclusive discount codes, content and product exchanges, early product access for top performers, and $2.3M in affiliate sales in one year. No cap statement is published, so the cap is honestly unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cbinsights.com/company/prx-performance', 'third_party_listing', 'company_background', 'CB Insights lists PRx Performance as founded in 2013 in Fargo, North Dakota, United States, manufacturing home gym equipment including foldable and freestanding squat racks.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 19, 16, 5, 9, 5, '{"compensation": "5% starting rate is average, but the performance structure rises to 12%, above the other equipment brands'' base rates in this batch.", "contact_access": "No published affiliate email or form found on fetched pages; the application is the only route in.", "credibility": "Shark Tank brand with platform-published results and an official register page.", "niche_fit": "Space-saving garage-gym racks are highly demonstrable, before/after-friendly UGC.", "opportunity_availability": "Live register page on the brand''s own site with a reported one-click approval flow.", "ugc_evidence": "Product/content exchanges, early product access and discount codes; the platform reports $2.3M in affiliate sales in one year."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Viator', 'https://www.viator.com', 'Marketplace for travel experiences and a Tripadvisor company, founded in 1995 and headquartered in San Francisco. Viator lists 300,000+ experiences in over 200 countries; its creator product, Viator Shop, lets creators organise and share recommendations through a single mobile-first tracking link built for link-in-bio, posts and stories.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Direct (Viator Partner Program)', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://partnerresources.viator.com/mc69293/.', 'https://partnerresources.viator.com/mc69293/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Viator Affiliate Program — For Creators / Viator Shop', 'https://partnerresources.viator.com/mc69293/', 'https://partnerresources.viator.com/mc69293/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partnerresources.viator.com/mc69293/', 'official_site', 'affiliate', 'Viator''s official creator resource page FAQ states ''Viator Affiliates earn 8% commission on any experience booked within 30 days'' (a $300 experience earns $24 if not cancelled), paid once the experience is completed; payouts are monthly bank transfers with a $50 minimum or weekly PayPal with no minimum. The page''s ''your commission never expires'' wording is an expiry statement, not an earnings-cap statement, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partnerresources.viator.com/mc69293/', 'official_site', 'ugc_collab', 'The page is built for creators: Viator Shop for social sharing, a ''See How Creators Are Curating Experiences in Viator Shop'' section, and links placeable in social media posts, YouTube video descriptions and blogs.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reverbico.com/blog/viator-affiliate-program/', 'article', 'affiliate', 'Third-party guide reports direct signup is free with no traffic or follower minimum via the Viator Partner Program, and that an Awin route exists in some markets at a lower 4% default.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 18, 14, 6, 10, 5, '{"compensation": "Flat 8% on any experience booked within 30 days, paid once the experience is completed; weekly PayPal with no minimum threshold.", "contact_access": "No published email or contact form verified on the fetched creator page.", "credibility": "Official resource centre fetched; a Tripadvisor company.", "niche_fit": "Tours and activities fit almost any travel itinerary content.", "opportunity_availability": "Open signup, free, with no traffic or follower minimum reported.", "ugc_evidence": "Dedicated creator Shop with link-in-bio design and a creator curation showcase on the official resource page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TRX Training', 'https://www.trxtraining.com', 'Maker of suspension training systems and functional training tools, founded by former Navy SEAL Randy Hetrick, who invented the TRX Suspension Trainer while deployed. Its systems, including Home2 and Pro4, suit trainers running bootcamps, clients who travel and at-home programs, with a reported average order value around $160-$200.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.trainerize.com/blog/health-and-fitness-affiliate-marketing/.', 'https://www.avantlink.com/signup/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TRX Affiliate Program', 'https://www.avantlink.com/signup/affiliate', 'https://theaffiliatemonkey.com/affiliate/trx-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.trainerize.com/blog/health-and-fitness-affiliate-marketing/', 'article', 'affiliate', 'Trainerize''s roundup (rates verified October 2026 from each program''s official page) lists TRX commission starting at 10% on US-based sales with a 30-day cookie, and links to the TRX Affiliate Program on trxtraining.com. GetLasso''s 15-30% listing conflicts with all other fetched sources and was not used. No cap statement is published, so the cap is honestly unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://commission.academy/blog/best-fitness-affiliate-programs/', 'third_party_listing', 'affiliate', 'Commission Academy lists TRX at a 10% base sales commission, 30-day cookie, integrated with AvantLink (Merchant ID 21449), $160 AOV, dedicated support and monthly payouts via AvantLink.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliatemonkey.com/affiliate/trx-affiliate-program/', 'third_party_listing', 'affiliate', 'The Affiliate Monkey lists a starting commission of 10% on all US-based sales with potential to earn more, $200 AOV and a 30-day cookie; joining is by signing up with AvantLink and then applying to TRX inside the network.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dornsife.usc.edu/news/stories/history-alumnus-fitness-entrepreneur-former-navy-seal-invents-trx-trainer/', 'article', 'company_background', 'USC Dornsife profile: Randy Hetrick, a 14-year Navy SEAL, invented the TRX Suspension Trainer while deployed.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 18, 5, 9, 5, '{"compensation": "10% starting rate on US sales is the highest verified base rate among this batch''s equipment brands, on a ~$160-$200 AOV; one directory''s 15-30% listing conflicts with all other sources and was not used.", "contact_access": "No direct brand affiliate email published on fetched pages; contact is via AvantLink only.", "credibility": "Category-defining US brand; terms consistent across 5+ independent fetched sources, though the brand''s own affiliate page could not be fetched in this run (429).", "niche_fit": "A single portable product, ideal for home, travel, bootcamp and short-form workout UGC.", "opportunity_availability": "Live and joinable via AvantLink signup, then an in-network application to TRX.", "ugc_evidence": "Long-standing creator/trainer promotion across many fetched reviews, with a dedicated affiliate support team; no explicit product-exchange perk found on fetched pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Klook', 'https://www.klook.com', 'Booking platform for experiences — attractions, tours, hotels, car rentals, trains and more — founded in September 2014 in Hong Kong. Alongside its affiliate program it runs the Kreator Program, its travel-influencer affiliate program with personalised links, Kreator Shops storefronts and a creator community.', 'Hong Kong', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliate@klook.com', null, 'https://affiliate.klook.com/en-MY/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Direct / Involve Asia', 5, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: high (see evidence). Rate as reported by https://affiliate.klook.com/en-MY/.', 'https://affiliate.klook.com/en-MY/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Klook Affiliate Program / Klook Kreator Program', 'https://affiliate.klook.com/en-MY/', 'https://affiliate.klook.com/en-MY/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliate.klook.com/en-MY/', 'official_site', 'affiliate', 'Klook''s official affiliate page offers exclusive partner codes, performance-based bonuses and widgets/search boxes/banners, and publishes the contact email affiliate@klook.com in its FAQ; it does not publish a commission percentage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://involve.asia/blog/klook-affiliate-program/', 'affiliate_network', 'affiliate', 'Involve Asia (a Klook network partner) lists category rates for Apr-Jun 2026 — tours/activities/hotels 6.5%, attractions/food/transport 5%, China high-speed rail 3.5%, special activities and gift cards 2%, Klook eSIM 20% — with a 30-day cookie (7 days for hotels/car rentals), and explicitly states the program ''has no commission cap'' on that route; the uncapped mark applies to the Involve Asia route where that wording appears. Ecomobi and Travelpayouts listings put the base at up to 5% on most categories, which is the base rate recorded here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.klook.com/newsroom/kreatorverse-2024-marcusyong-social/', 'official_site', 'creator_saturation', 'Klook executive interview on klook.com: the Kreator Program launched in 2023 with ''over 20,000 creators hailing across 16 markets'', personalised affiliate links, an affiliate manager, Kreator Shops and TikTok bookable-content partnerships.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Phocuswire.com/news/technology/klook-kreator-shops-travel-social-media-influencer', 'article', 'creator_saturation', 'PhocusWire reports Kreator Shops opened to ''more than 30,000 creators across 88 markets'', and that joining the Kreator Program requires a minimum of 1,000 followers on a social platform (higher in some markets) — hard evidence for the high-saturation mark.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 10, 13, 7, 5, '{"compensation": "Lowest and least transparent base in this batch: 5% network-reported, the official page publishes no rate, and routes conflict; Involve Asia states that route has no commission cap.", "contact_access": "Published affiliate email (affiliate@klook.com) plus a Contact Us route on the official affiliate page.", "credibility": "Official affiliate portal and newsroom fetched.", "niche_fit": "Broad experiences catalogue; strongest in Asia-Pacific versus a US-first audience.", "opportunity_availability": "Open affiliate signup, but the Kreator Program has follower minimums (1,000+) and the cohort already exceeds 30,000 creators.", "ugc_evidence": "Dedicated Kreator influencer program with storefronts, events and manager support \u2014 the strongest creator infrastructure in this batch."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Allbirds', 'https://www.allbirds.com', 'Footwear and apparel brand known for minimalist, sustainability-led design. Its own affiliate page recruits two tracks: Social Ambassadors promoting through Instagram, TikTok or YouTube, and Media Publications promoting through publications, email newsletters, podcasts or blogs — both for a commission on all net sales, with social ambassadors also in line for free products.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'help@allbirds.com', null, 'https://allbirds.superfiliate.com/portal/signUp', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Superfiliate / Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.allbirds.com/pages/affiliates.', 'https://www.allbirds.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Allbirds Affiliate Program — Social Ambassadors (Superfiliate) / Media Publications (Impact)', 'https://www.allbirds.com/pages/affiliates', 'https://www.allbirds.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.allbirds.com/pages/affiliates', 'official_site', 'affiliate', 'Allbirds'' own affiliate page (fetched in full) offers two tracks — Social Ambassadors via Superfiliate and Media Publications via Impact — each for ''a commission on all net sales'', with potential free products for social ambassadors. The page publishes no percentage rate, cookie term or cap statement, so the rate is recorded as null and the cap as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://allbirds.superfiliate.com/portal/signUp', 'affiliate_network', 'affiliate', 'Live Superfiliate sign-up portal for Allbirds; its Terms identify the US operator AB Dnam, LLC, a Florida limited liability company with its principal place of business at 8484 Wilshire Blvd., Beverly Hills, CA 90211, and publish the help email help@allbirds.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bloop.plus/blog/affiliate-program-terms-and-conditions/', 'third_party_listing', 'affiliate', 'An independent audit of brand affiliate pages (Oct 2026) likewise records Allbirds as ''commission on all net sales (rate not shown)'', with full terms in Superfiliate and Impact — corroborating the null rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/allbirds/', 'third_party_listing', 'affiliate', 'Third-party directories conflict on Allbirds'' rate (Lasso 2.4%, Uppromote 1-15%, Shopper 5-10% and others); none was adopted, because the brand''s own page and portal publish no percentage.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 8, 10, 9, 5, '{"compensation": "A real commission mechanism (''commission on all net sales'') but the rate is not published on the brand''s page or portal, so it cannot be scored higher honestly; third-party figures (1-15%) conflict and were not adopted.", "contact_access": "Published help email on the sign-up portal; no affiliate-specific contact.", "credibility": "The brand''s own affiliate page and sign-up portal were fetched in full.", "niche_fit": "Footwear/fashion with an explicit TikTok/Instagram/YouTube social track \u2014 ideal for creators.", "opportunity_availability": "Two live Apply Now routes from the official page.", "ugc_evidence": "The brand itself solicits social ambassadors and media publishers across social channels, blogs, podcasts and newsletters; no creator counts published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vessi', 'https://vessi.com', 'Vancouver-based footwear brand founded in 2017 by Tony Yu, Andy Wang and Mikaella Go, making waterproof shoes with its patented Flashknit material, which it says keeps the waterproofing from wearing out. Its affiliate manager pitches the program to anyone with an audience of active-lifestyle adults and outdoor enthusiasts.', 'Canada', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'support.us@vessi.com', null, 'https://vessi.com/a/faq', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by http://www.tacticalmarketingco.com/partner-with-us.', 'http://www.tacticalmarketingco.com/partner-with-us', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vessi Footwear Affiliate Program — ShareASale: 10% Commission', 'http://www.tacticalmarketingco.com/partner-with-us', 'http://www.tacticalmarketingco.com/partner-with-us', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.tacticalmarketingco.com/partner-with-us', 'affiliate_network', 'affiliate', 'The program manager''s page (fetched in full) lists ''VESSI — SHAREASALE: 10% COMMISSION … Earn 10% commission on all sales with a 30 day tracking cookie.'' No cap statement is published, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/vessi-footwear/', 'third_party_listing', 'affiliate', 'Lasso independently lists Vessi Footwear at 10% per sale with a 30-day cookie, matching the manager listing.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/127441/vessi-footwear-affiliate-program', 'affiliate_network', 'company_background', 'Sovrn''s merchant summary describes Vessi as a Vancouver-based footwear brand founded in 2017 by Tony Yu, Andy Wang and Mikaella Go; Sovrn states it could not verify its own Vessi rate, so it was not used for the rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 16, 5, 8, 4, '{"compensation": "Clean flat 10% per sale with a 30-day cookie, per the program manager''s listing and corroborated by Lasso.", "contact_access": "Only a general support email found on the brand''s FAQ page; no affiliate-specific contact.", "credibility": "Manager listing fetched in full plus directory corroboration; the brand''s own affiliate page was not found.", "niche_fit": "Fashion footwear with an active-lifestyle and outdoor creator fit.", "opportunity_availability": "Live ShareASale program via the program manager.", "ugc_evidence": "The program explicitly targets audience owners; no creator counts fetched."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tonal', 'https://tonal.com', 'US wall-mounted connected strength system that learns the user''s abilities, selects the right challenges and adjusts resistance as they improve, offering 340+ exercises in an all-in-one design. Its affiliate program pays a flat bounty per system sold; its separate member referral program cannot be used for affiliate lead generation.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'LinkApprove', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkapprove.com/affiliate-programs/tonal-affiliate-program.', 'https://linkapprove.com/affiliate-programs/tonal-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tonal Affiliate Program — $100 per sale', 'https://linkapprove.com/affiliate-programs/tonal-affiliate-program', 'https://linkapprove.com/affiliate-programs/tonal-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/tonal-affiliate-program', 'affiliate_network', 'affiliate', 'LinkApprove''s program page: Tonal pays a flat $100 per system sold on a 30-day cookie (not a percentage, so the rate is recorded as null), free to join with no separate Tonal application, decision usually within 2 business days, AOV $3,200, regions US and CA. No cap statement is published for the bounty, so the cap is honestly unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tonal.com/pages/referralterms', 'official_site', 'affiliate', 'Tonal''s official referral terms (effective Nov 17, 2025) confirm the member Referral Program is distinct from the affiliate program and ''cannot be used by businesses for affiliate lead generation''; its 3-months-membership advocate reward (capped at 3 rewards per 365 days) is not affiliate commission.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/health-affiliate-programs/', 'third_party_listing', 'affiliate', 'CompareEPC lists Tonal on Impact at 1% / $5.66 EPC, which conflicts with LinkApprove''s flat $100 bounty; the flat bounty is recorded and the percentage listing was not adopted.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 10, 17, 3, 8, 4, '{"compensation": "A flat $100 bounty per system sold (30-day cookie) is high per conversion on a ~$3,200 product, despite low volume; a conflicting 1% Impact listing was not adopted, so the rate is recorded as a flat bounty, not a percentage.", "contact_access": "No published affiliate email or form; joining is via the network only.", "credibility": "Detailed network program page, but no rate is published on tonal.com itself.", "niche_fit": "Premium home strength system \u2014 perfect for strength and home-gym creators, though narrower than nutrition.", "opportunity_availability": "Live via LinkApprove with no separate Tonal application; decision usually within 2 business days.", "ugc_evidence": "The program targets publishers and reviewers; no creator/UGC programme details were found on the brand''s own site."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('OLIPOP', 'https://drinkolipop.com', 'Prebiotic soda brand founded in 2018 by Ben Goodwin and David Lester and based in Oakland, California, making sodas with fiber and prebiotics that support gut health.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'partnerships@drinkolipop.com', null, 'https://theaffiliatemonkey.com/affiliate/olipop-affiliate-program/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://drinkolipop.com/pages/affiliate-program.', 'https://drinkolipop.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'OLIPOP Affiliate Program (Impact)', 'https://drinkolipop.com/pages/affiliate-program', 'https://drinkolipop.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://drinkolipop.com/pages/affiliate-program', 'official_site', 'affiliate', 'OLIPOP''s official affiliate page invites creators with an established community or audience to partner, states the program runs on Impact.com, and publishes a 10% baseline payout (earn up to 20%), a 7-day click referral window and a conversion rate above 12%. The ''up to 20%'' wording is a rate tier, not an earnings-cap statement, and no explicit no-cap or unlimited-earnings statement was found, so the commission cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/olipop', 'creator_directory', 'creator_saturation', 'Beacons Universe reports posts from 2,068 creators all time (150 posted in the last 30 days), 138 sponsored posts mentioning OLIPOP in the last 12 months and 1,384 public posts in the last 12 months, so creator saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://impact.com/influencer/creator-community-olipops-hybrid-commission-approach/', 'article', 'affiliate', 'Impact''s case study says OLIPOP manages nearly 2,000 creator relationships including 82 registered dietitians, created over 1,400 custom codes in three years, requires a minimum of 10,000 followers on at least one platform (with dietitian exceptions), and that the creator affiliate program launched in 2021 and contributes 12% of total sales.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliatemonkey.com/affiliate/olipop-affiliate-program/', 'third_party_listing', 'contact', 'A directory page for the OLIPOP affiliate program publishes partnerships@drinkolipop.com as the contact for program questions (''Apply through Impact.com or email partnerships@drinkolipop.com if you have questions'').', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 20, 15, 13, 6, 5, '{"niche_fit": "Prebiotic soda is a top food-and-drink creator niche with strong retail and DTC presence.", "ugc_evidence": "Nearly 2,000 managed creator relationships, 82 registered dietitians and 1,400+ custom codes documented by Impact.", "compensation": "10% baseline payout on the official page, rising to 20%, with a stated conversion rate above 12%.", "contact_access": "Published partnerships email plus a direct Impact application route.", "opportunity_availability": "Program is open but generally requires at least 10,000 followers on one platform.", "credibility": "Founded 2018, Oakland-based, program managed with Impact and agency GravityFed."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Goli Nutrition', 'https://goli.com', 'Gummy supplement brand founded in 2019, known for apple cider vinegar and ashwagandha gummies that are vegan, gluten-free and gelatin-free, sold through its own store, retail and TikTok Shop.', null, 'published') returning id into bid;
