  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'tts@goli.com', null, 'https://goli.com/pages/rewardterms', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'In-house (Goli Partners) / TikTok Shop', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://ca.goli.com/pages/faq-ashwagandha.', 'https://partners.goli.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Goli Partners Program', 'https://partners.goli.com', 'https://ca.goli.com/pages/faq-ashwagandha', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ca.goli.com/pages/faq-ashwagandha', 'official_site', 'affiliate', 'Goli''s official FAQ answers the partner question with ''We do! Please contact us at partners@goli.com if you love our Goli Gummies and want to become part of the Goli extended family!'', confirming a partner program with a published contact email. No earnings-cap statement appears on the page, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandchamp.io/blog/customer-loyalty-programs-gummy-supplements/', 'article', 'affiliate', 'BrandChamp''s description of the Goli Partners Program (applied for at partners.goli.com by anyone 18+ with a regularly updated social page) says ambassadors start at 10% commission with a 10% follower discount, rising to 20% commission and a 15% follower discount above 200 sales per month, with PayPal payout from a $10 balance. Other listings conflict (Lasso lists up to 18.75%; one review lists a standard 3% affiliate rate and tiered 10-25%), so the 10% Partners starting rate is used and the conflict is flagged here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://goli.com/pages/rewardterms', 'official_site', 'affiliate', 'Goli''s official TikTok Shop reward campaign page addresses brand affiliates directly, publishes affiliate support contact tts@goli.com, and describes bonus rewards on top of commissions for TikTok Shop sales; the bonus thresholds are promotional rewards, not an earnings cap.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://joinbrands.com/case-studies/goli-nutrition/', 'agency_case_study', 'creator_saturation', 'JoinBrands'' case study says more than 2,000 creators were activated for Goli in Target stores through its managed service, so creator saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 13, 14, 8, 4, '{"niche_fit": "Gummy supplements are a proven, high-volume creator category across TikTok and Instagram.", "ugc_evidence": "2,000+ creators activated in one managed campaign plus an official TikTok Shop affiliate campaign.", "compensation": "Partners start at 10% commission per BrandChamp''s program description, rising to 20% at volume; listings conflict, so this needs re-confirmation at sign-up.", "contact_access": "Two published emails: partners@goli.com for partnerships and tts@goli.com for affiliate support.", "opportunity_availability": "Partners application is open to anyone 18+ with a regularly updated social page.", "credibility": "B Corp certified brand founded in 2019; HQ and founding details conflict across sources, so credibility is held at 4."}'::jsonb);
