  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Whisker Affiliate & Influencer Program — 8% commission, 90-day cookie, $650+ new-customer AOV', 'https://www.litter-robot.com/affiliates.html', 'https://www.litter-robot.com/affiliates.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.litter-robot.com/affiliates.html', 'official_site', 'affiliate', 'Official Whisker partnerships page fetched: three tracks — Publishers & affiliates (must have content-focused sites/channels, domain rating 20+; new customer AOV $650+, 90-day cookie, ''competitive commission rate'' — no percentage published on the page), Influencers & personalities (10k+ followers on Instagram/TikTok/YouTube, tiered compensation and product trade, early access and free product collaborations) and pet industry professionals (commission for successful referrals); program ''not designed for digital marketers''; media inquiries to pr@whisker.com published on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-programs/cat/', 'listing', 'affiliate', 'UpPromote cat-program roundup fetched: Litter-Robot offers an 8% commission with a 90-day cookie duration and average order value over $550, plus a $50 audience discount; program focuses on publishers and content creators.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliateslist.com/cat-affiliate-programs/', 'listing', 'affiliate', 'The Affiliates List fetched: Litter-Robot.com pays 8% of revenue with a 90-day cookie and AOV above $550, and partners with Ascend (Partnerize) to manage three affiliate tracks (brand influencers, affiliate content creators, customer referrals). The official Whisker affiliate terms (hosted at affi.io) state the program is administered by Pepperjam, LLC — Ascend is Partnerize''s successor platform to Pepperjam. A Lasso marketplace listing separately advertises ''up to 9.0%'', and one older roundup claimed 5%-7% via Impact, so the 8% figure is the corroborated one recorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/litter-robot', 'listing', 'ugc_collab', 'Beacons Universe fetched: Litter-Robot (based in Auburn Hills, United States) has posts from 216 creators all time, 137 public posts in the last 12 months and 32 sponsored posts in the last 12 months, with sponsored reels as recent as November 2026 — an active mid-size creator programme, not low enough to record saturation as low.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 16, 9, 7, 5, '{"niche_fit": "Flagship pet-tech product \u2014 a self-cleaning litter box is one of the most demonstrable, before/after-friendly products in pet UGC", "ugc_evidence": "Dedicated official influencer track (10k+ followers) with tiered compensation, free product collaborations and creator campaigns, plus Beacons volume of 216 creators and 32 sponsored posts in the last 12 months", "compensation": "8% on a $650+ new-customer AOV is roughly $44-$52 per sale with a long 90-day cookie; the official page itself publishes no percentage (''competitive rate''), and no cap statement is published anywhere fetched, so cap is unknown", "contact_access": "Published pr@whisker.com media contact on the official partnerships page, but no dedicated affiliate email; application is via the partnerships page/network", "opportunity_availability": "Application is gated \u2014 publishers need a domain rating of 20+ and influencers 10k+ followers, so it is not open to beginners", "credibility": "Established US smart-pet-care leader (Auburn Hills, Michigan) with national retail presence and a 2026 TikTok Shop launch"}'::jsonb);
