  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://develop.netlify.lettucegrow.com/affiliate', 'official_site', 'affiliate', 'Official Lettuce Grow affiliate page fetched (brand''s own affiliate page, served from its staging mirror): ''Join our exclusive affiliate program if you share our values, love Lettuce Grow''s products, and have an audience eager to embrace sustainable, homegrown living''; affiliates ''earn a portion of every sale referred'' with performance incentives and cash bonuses; FAQ states tracking, reporting and payments are handled by the ShareASale affiliate network, sign-up is free and applications are reviewed by the team; contact published as affiliate@lettucegrow.com. The page publishes NO commission percentage.', 'verified', now());
