  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Team Viva / Viva Partner — earn $15 Viva credit per referred order plus free food (rewards-based, no cash commission published)', 'https://vivarawpets.com/pages/affiliates', 'https://vivarawpets.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://vivarawpets.com/pages/affiliates', 'official_site', 'affiliate', 'Official Viva Raw affiliates page fetched: four programmes — Viva Partner (seasoned content creators, rescues, trainers and pet care professionals; sneak peeks, early access and extended free-food opportunities), Viva Breeder, Viva Vet (lifetime discount and free samples) and Team Viva (open to everyone; unique discount code and a customisable webpage with your own videos and message); FAQ: ''With each referral, you''ll earn credit that can be redeemed for free food!'' — rewards are store credit/free food, and no cash commission percentage is published anywhere on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://viva.frontkb.com/en/articles/7264961', 'official_site', 'affiliate', 'Official Viva Raw help centre fetched: ''Team Viva is our affiliate program for pet parents... Once you join, you''ll get a unique referral link and code. Every time someone places an order using your link, you''ll receive a $15 Viva credit, and they''ll get a discount on their first purchase!'' — the only published reward figure is a flat $15 store credit per referred order.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 10, 8, 9, 4, '{"niche_fit": "Raw feeding is a passionate, content-rich pet niche \u2014 meal prep, transitions and results content performs strongly in UGC", "ugc_evidence": "A dedicated Viva Partner track built specifically for seasoned content creators, with customisable referral webpages designed to host the creator''s own videos, plus an open Team Viva tier", "compensation": "Rewards-based only: $15 store credit per referred order plus free food and perks; no cash commission percentage is published anywhere, so the rate is null; no cap statement published", "contact_access": "Application forms on the official affiliates page; no partnerships email was published on the fetched pages", "opportunity_availability": "Team Viva is open to everyone with quick sign-up; Partner/Breeder/Vet tracks are application-based", "credibility": "Established US DTC raw pet food brand with an official help centre documenting the programmes"}'::jsonb);
