  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://chipolo.net/en/pages/get-a-free-chipolo-rules', 'official_site', 'affiliate', 'Official Chipolo referral rules page fetched: the customer ''Get a Free Chipolo'' programme gives a FREE Chipolo product (not cash commission) after three friends purchase through a referral link, with friends receiving 20% off; the page is published by Chipolo d.o.o. under Slovenian law (District Court in Ljubljana). IMPORTANT: this ''free product for referrals'' wording relates only to free referral products — it is not an earnings-cap statement about the affiliate program, so commission_cap is honestly recorded as unknown.', 'verified', now());
