  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.meetmaev.com/club', 'official_site', 'ugc_collab', 'Official Maev ''The Club'' page fetched: ''Welcome to the club, the community of Maev Ambassadors, for dog people and design people. Apply to join us today.'' Ambassadors are ''a diverse community of creatives, innovators, designers'' who bring the brand to life in their communities; perks are insider access, first looks at product releases, exclusive discounts, access to Team Maev and rewards ''for being a thought-leader (and for inspiring others to try Maev)''. No commission percentage, cash rate or affiliate network is published anywhere on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.honestbrandreviews.com/reviews/maev-dog-food-review/', 'listing', 'affiliate', 'Honest Brand Reviews fetched: Maev''s customer rewards programme gives 1 point per $1 spent (10 points = $1 off), with referral rewards of $20 off for the referred friend and $20 worth of points for the referrer — a points/referral scheme, not a published creator commission; the review also confirms Maev is a subscription service providing flash-frozen raw dog food.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 6, 7, 8, 4, '{"niche_fit": "Premium raw dog food aimed at design-conscious urban owners is a distinctive, content-friendly pet niche", "ugc_evidence": "A named ambassador community (''The Club'') explicitly built around creatives and designers creating in their communities, but no creator counts are published", "compensation": "No commission percentage or cash rate is published anywhere fetched \u2014 ambassadors earn unspecified ''rewards'' and exclusive discounts, and the customer programme is points-based ($20 referral points), so the rate is null; no cap statement published", "contact_access": "Application via the official Club page; no partnerships email was published on the fetched pages", "opportunity_availability": "Open application to join The Club from the official site", "credibility": "Established US DTC raw dog food brand with national review coverage"}'::jsonb);
